    private val EPOCH_JD = 2440587.5
    private val MS_PER_DAY = 86400000.0

    /** 儒略日 -> 北京时间 LocalDateTime（sxtwl 的 jd 换算出的即为北京时间数值，无需再加时区偏移） */
    private fun jdToLocal(jd: Double): LocalDateTime {
        val utcMillis = ((jd - EPOCH_JD) * MS_PER_DAY).toLong()
        return LocalDateTime.ofEpochSecond(utcMillis / 1000, 0, ZoneOffset.UTC)
    }

    /** 查询某公历年、某节气索引(0=冬至,1=小寒,...,23=大雪)的精确时刻 */
    fun termTime(year: Int, jqIndex: Int): LocalDateTime? {
        if (year < 1900 || year > YEAR_END || jqIndex !in 0..23) return null
        val jd = if (year in YEAR_START..YEAR_END) {
            TABLE[year - YEAR_START][jqIndex]
        } else {
            // 1900-1989 早年回退表（同源天文算法离线生成）
            SolarTermEarly.TABLE[year - 1900][jqIndex]
        }
        if (jd <= 0.0) return null
        return jdToLocal(jd)
    }

    /** 查询某公历年、某节气名称的精确时刻 */
    fun termTime(year: Int, name: String): LocalDateTime? {
        val i = NAMES.indexOf(name)
        return if (i < 0) null else termTime(year, i)
    }

    data class TermInfo(val name: String, val time: LocalDateTime) {
        /** jishiyu 原版格式: 立冬2026-11-07 17:51 (去掉秒) */
        val display: String get() = "$name${time.format(java.time.format.DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm"))}"
    }
    data class TermRange(val from: TermInfo, val to: TermInfo)

    /**
     * 查询时刻所在的节气区间: [上个节气, 下个节气)。
     * 用 jqIndex 0..23 在时间上并非自然顺序(0=冬至在12月), 故展开为时间有序列表再定位。
     */
    fun rangeAt(dt: LocalDateTime): TermRange? {
        val y = dt.year
        if (y < 1900 || y > YEAR_END) return null
        val list = mutableListOf<Pair<Int, LocalDateTime>>()
        for (yy in (y - 1)..(y + 1)) {
            if (yy < 1900 || yy > YEAR_END) continue
            val row = if (yy in YEAR_START..YEAR_END) TABLE[yy - YEAR_START] else SolarTermEarly.TABLE[yy - 1900]
            for (i in 0..23) {
                if (row[i] <= 0.0) continue
                list.add(i to jdToLocal(row[i]))
            }
        }
        list.sortBy { it.second }
        for (k in list.indices) {
            if (dt >= list[k].second && (k + 1 >= list.size || dt < list[k + 1].second)) {
                val from = list[k]
                val to = list.getOrNull(k + 1) ?: from
                return TermRange(TermInfo(NAMES[from.first], from.second), TermInfo(NAMES[to.first], to.second))
            }
        }
        return null
    }
}
